    13	type SessionDataT = Record<string, any>;
    14	
    15	export type SessionData<T extends SessionDataT = SessionDataT> = Partial<T>;
    16	
    17	export interface Session<T extends SessionDataT = SessionDataT> {
    18	  id: string;
    19	  /** Time the session was created. The point `maxAge` is measured from. */
    20	  createdAt: number;
    21	  /**
    22	   * Time the session was last resealed. Only stamped when `idleTimeout` is set,
    23	   * and the point the idle window is measured from.
    24	   */
