    51	/** MAC normalization format version. */
    52	export const macFormatVersion = "2";
    53	
    54	/** MAC normalization prefix. */
    55	export const macPrefix = "Fe26.2"; // `Fe26.${macFormatVersion}`
    56	
    57	/** Serializes, encrypts, and signs objects into an iron protocol string. */
    58	export async function seal(
    59	  object: Readonly<unknown>,
    60	  password: Readonly<RawPassword>,
    61	  opts: Readonly<SealOptions>,
    62	): Promise<string> {
    63	  const now = Date.now() + (opts.localtimeOffsetMsec || 0);
    64	
    65	  if (!password) {
    66	    throw new Error("Empty password");
    67	  }
    68	  const { id = "", encryption, integrity } = normalizePassword(password);
    69	  if (id && !/^\w+$/.test(id)) {
    70	    throw new Error("Invalid password id");
    71	  }
    72	
    73	  // prettier-ignore
    74	  const { encrypted, key } = await encrypt(encryption, opts.encryption, JSON.stringify(object));
    75	
    76	  const encryptedB64 = base64Encode(encrypted);
    77	  const iv = base64Encode(key.iv);
    78	  const expiration = opts.ttl ? now + opts.ttl : "";
    79	  const macBaseString = `${macPrefix}*${id}*${key.salt}*${iv}*${encryptedB64}*${expiration}`;
    80	
    81	  const mac = await hmacWithPassword(integrity, opts.integrity, macBaseString);
    82	  const sealed = `${macBaseString}*${mac.salt}*${mac.digest}`;
    83	  return sealed;
    84	}
